      "reason": "The title explicitly includes the phrase 'A Systematic Review', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Review Article > Treatment Options In Extra-Articular Distal Radius Fractures: A Systematic Review And Meta-Analysis",
      "reason": "The title specifies the population ('extra-articular distal radius fractures') and the focus on interventions ('Treatment Options'), providing key information about the main objective/review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Review Article > Treatment Options In Extra-Articular Distal Radius Fractures: A Systematic Review And Meta-Analysis",
      "reason": "The title includes 'Meta-Analysis', which reports the analysis method as supplementary information."
