  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Current literature does not provide enough evidence to support superiority of a particular treatment method for extraarticular distal radius fractures, when looking at complications, re-interventions, and long-term functional outcomes. A broad range of outcome parameters have been used, which makes the data partly impossible to compare. From a methodological point of view, the quality of data used in this systematic review and subsequent conclusions that can be drawn, appear to be rather weak.",
      "reason": "The manuscript explicitly describes the current state of knowledge and important uncertainties (lack of evidence of superiority, heterogeneity of outcome measures, and weak methodological quality)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Purpose This systematic literature review aimed to make a detailed overview on the clinical and functional outcomes and to get insight into the possible superiority of a treatment method for extra-articular distal radius fractures .",
      "reason": "The abstract states the purpose and explains the need to overview outcomes and investigate possible superiority of treatments, indicating the importance and rationale for conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence discusses existing similar systematic reviews, nor cites or explains the need relative to prior reviews; therefore this reporting element is not reported."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not describe a proposed mechanism of action for the interventions; only clinical outcomes and comparisons are reported without mechanistic explanation."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Five treatment modalities were compared: plaster cast immobilization, K-wire fixation, volar plating, external fixation, and intramedullary fixation .",
      "reason": "The review compares discrete surgical and non-surgical treatment modalities rather than complex multi-component or delivery-context interventions; a logic model for complex interventions is therefore not applicable."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Purpose This systematic literature review aimed to make a detailed overview on the clinical and functional outcomes and to get insight into the possible superiority of a treatment method for extra-articular distal radius fractures .",
      "reason": "The review objective is explicitly stated (to overview clinical and functional outcomes and assess possible superiority of treatments for extra-articular distal radius fractures), but it is not framed using a recognized question-formulation framework (e.g., PICO) in the provided text, so the requirement to use a relevant framework is only partially met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Five treatment modalities were compared: plaster cast immobilization, K-wire fixation, volar plating, external fixation, and intramedullary fixation .",
      "reason": "For an intervention review, the planned comparisons are stated by listing the five treatment modalities compared; the population (extra-articular distal radius fractures) and outcomes (clinical and functional outcomes, complications, re-interventions) are described elsewhere in the abstract and manuscript, fulfilling the PICO-style specification of planned comparisons."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The studies were eligible for inclusion if they met the following criteria: (1) Patients who suffered and were treated for an extra-articular distal radius fracture; (2) age 18 years or older; (3) patients were either treated using a plaster cast, K-wire(s), plate fixation, external fixator, or an intramedullary device; (4) primary data for at least one outcome parameter had to be available.",
      "reason": "The manuscript specifies key study characteristics used for eligibility: patient condition, age threshold, eligible interventions/treatments, and requirement for primary outcome data."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "A literature search was conducted June 19, 2018. Embase, Medline, The Cochrane Library, Web of Science, and Google Scholar were searched to identify relevant clinical studies that report on the outcomes of extra-articular distal radius fractures. ... No language limits were used and any potentially eligible non-English language manuscripts were translated if possible by native speaking colleagues or using Google translate, if no native speaker was available.",
      "reason": "The review reports the search date and explicitly states no language limits (and translation approach), but it does not explicitly state restrictions by dissemination year beyond the search date or specify publication/report status criteria (e.g., grey literature inclusion/exclusion)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "Studies without a clear description of fracture type or intervention, or studies that lacked sufficient data for analysis were excluded. In addition, studies with incomplete registration of complications were excluded.",
      "reason": "The text lists exclusions for insufficient data or incomplete registration but does not distinguish exclusions because outcomes were not measured from exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "These 136 cohorts consisted of a total of 6707 patients divided over the five different treatment modalities. ... All outcome data were pooled for four different follow-up periods: 0-3 months, > 3-6 months, > 6-12 months, and 12 months or longer (long term).",
      "reason": "The review specifies groups used in syntheses (five treatment modalities) and links outcome pooling to defined follow-up periods, aligning groups with comparisons of interest."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies describing a not-commonly used device or technique for extra-articular fractures were excluded ( i.e. dorsal plates, Epibloc system, cannulated screw, above elbow cast, etc.).",
      "reason": "The manuscript provides a rationale for a notable restriction (exclusion of not-commonly used devices/techniques) and gives examples of such excluded interventions."
    }
  ],
  "confidence": 80
}

